from fractions import Fraction

def is_rational_square(f: Fraction) -> bool:
    """Checks if a positive rational number f is the square of a rational number."""
    if f <= 0:
        return False

    # Get numerator and denominator in reduced form
    num = f.numerator
    den = f.denominator

    # Check if both are perfect squares
    def is_perfect_square(n):
        if n < 0:
            return False
        if n == 0:
            return True
        # Calculate integer square root
        sqrt_n = int(n**0.5)
        return sqrt_n * sqrt_n == n

    return is_perfect_square(num) and is_perfect_square(den)

a_values = [0, 1, -1, 3, Fraction(1, 2), Fraction(2, 3)]
results = []

for a in a_values:
    # Calculate b^2 = (a^3 - 2a^2 - a) / (a - 2)
    try:
        numerator = a**3 - 2*a**2 - a
        denominator = a - 2

        if denominator == 0:
            b_squared = None
        else:
            b_squared = numerator / denominator

        print(f"--- Testing a = {a} ---")
        if b_squared is None:
            print("Denominator is zero (a=2), skipping.")
            continue

        # Check if non-negative
        if b_squared < 0:
            print(f"RHS ({b_squared}) is negative. Skipping.")
            continue

        # Check if it is a rational square
        if is_rational_square(b_squared):
            # Find b. We only need one solution for b (positive or negative).
            # Since the problem asks for pairs (a, b), and b^2 is found, b = +/- sqrt(b^2).
            # We can represent b as +/- sqrt(b^2) or just use the fact that it exists.
            # To record the solution, we note that b must be rational.
            results.append((a, b_squared))
            print(f"SUCCESS! b^2 = {b_squared} is a rational square. Solutions for b exist.")
        else:
            print(f"RHS ({b_squared}) is non-negative but NOT a rational square.")

    except Exception as e:
        print(f"An error occurred for a={a}: {e}")

print("\nSummary of results (a, b^2):", results)
